-- The id is generated by the application before the insert, because the
-- same id names the hold in Redis (resv:{id}) created by the reserve script.
CREATE TABLE bookings (
    id UUID PRIMARY KEY,
    user_id INTEGER NOT NULL REFERENCES users(id),
    event_id INTEGER NOT NULL REFERENCES events(id),
    status booking_state NOT NULL DEFAULT 'PENDING',
    -- Price locked at reserve time, in the smallest currency unit
    total_cents INTEGER NOT NULL CHECK (total_cents >= 0),
    payment_idempotency_key VARCHAR(255) UNIQUE,
    payment_intent_id VARCHAR(255) UNIQUE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    expires_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);

SELECT diesel_manage_updated_at('bookings');

CREATE INDEX bookings_status_expires_at_idx ON bookings (status, expires_at);
CREATE INDEX bookings_user_id_idx ON bookings (user_id);
CREATE INDEX bookings_event_id_idx ON bookings (event_id);

CREATE TABLE event_seats (
    id SERIAL PRIMARY KEY,
    event_id INTEGER NOT NULL REFERENCES events(id),
    seat_id INTEGER NOT NULL REFERENCES seats(id),
    -- Offset of this seat in the Redis bitfield seats:{event}
    seat_index INTEGER NOT NULL CHECK (seat_index >= 0),
    status seat_status NOT NULL DEFAULT 'AVAILABLE',
    -- Set only when the seat is sold; holds live in Redis
    booking_id UUID REFERENCES bookings(id),
    price_cents INTEGER NOT NULL CHECK (price_cents >= 0),
    version INTEGER NOT NULL DEFAULT 0,
    UNIQUE (event_id, seat_id),
    -- Also the index for reading an event's seat map in seat_index order
    UNIQUE (event_id, seat_index),
    CHECK ((status = 'SOLD') = (booking_id IS NOT NULL))
);

CREATE INDEX event_seats_event_id_status_idx ON event_seats (event_id, status);

-- Seats held by each booking, kept after expiry as history. Used to rebuild
-- the Redis seat map for bookings that are still PENDING or PAYMENT_PENDING.
CREATE TABLE booking_seats (
    booking_id UUID NOT NULL REFERENCES bookings(id),
    event_seat_id INTEGER NOT NULL REFERENCES event_seats(id),
    PRIMARY KEY (booking_id, event_seat_id)
);

CREATE INDEX booking_seats_event_seat_id_idx ON booking_seats (event_seat_id);

CREATE TABLE payment_inbox (
    id BIGSERIAL PRIMARY KEY,
    provider VARCHAR(50) NOT NULL,
    provider_event_id VARCHAR(255) UNIQUE NOT NULL,
    event_type VARCHAR(100) NOT NULL,
    payload JSONB NOT NULL,
    received_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    processed_at TIMESTAMPTZ,
    attempts INTEGER NOT NULL DEFAULT 0,
    last_error TEXT
);

-- The payment worker only scans unprocessed rows
CREATE INDEX payment_inbox_unprocessed_idx ON payment_inbox (received_at)
    WHERE processed_at IS NULL;
